import { lineChart } from '../components.js';
import {
  resilientBackendScaling,
  ssoLowThreshold,
  ssoProportional,
} from '../data/evaluation-results.js';

const phaseDefinitions = {
  registration: { title: 'Registration', key: 'registration' },
  authentication: { title: 'Authentication', key: 'authentication' },
  'password-update': { title: 'Password Update', key: 'passwordUpdate' },
  'secret-update': { title: 'Secret Update', key: 'secretUpdate' },
};

const lowSlides = {
  'aux-sso-low-registration': phaseDefinitions.registration,
  'aux-sso-low-authentication': phaseDefinitions.authentication,
  'aux-sso-low-password-update': phaseDefinitions['password-update'],
};

const asymptoticSlides = {
  'aux-sso-asymptotic-registration': phaseDefinitions.registration,
  'aux-sso-asymptotic-authentication': phaseDefinitions.authentication,
  'aux-sso-asymptotic-password-update': phaseDefinitions['password-update'],
};

const resilientSlides = {
  'aux-resilient-registration': phaseDefinitions.registration,
  'aux-resilient-secret-update': phaseDefinitions['secret-update'],
  'aux-resilient-password-update': phaseDefinitions['password-update'],
};

const panelLabels = {
  client: 'Client',
  provider: 'Storage Provider',
  lan: 'LAN',
  wan: 'WAN',
  local: 'Complete local',
};

function slideFrame(title, kind, charts) {
  return `<div class="slide-shell evaluation-aux-slide" data-evaluation-kind="${kind}">
    <h2>${title}</h2>
    ${kind === 'resilient' ? '' : '<div class="eval-shared-legend"><span class="upspa">UpSPA</span><span class="pastau">PAS-TA-U</span><span class="augsso">AugSSO</span></div>'}
    <div class="evaluation-chart-grid ${kind}">${charts}</div>
  </div>`;
}

function chartPanel({ dataset, panelKey, phaseTitle, kind, index }) {
  const panel = dataset.panels[panelKey];
  const [yMin, yMax] = panel.domain || [];
  const asymptotic = kind === 'asymptotic';
  const resilient = kind === 'resilient';
  return `<article data-panel="${panelKey}">${lineChart({
    labels: dataset.labels,
    series: panel.series,
    yMin,
    yMax,
    yScale: resilient ? 'log' : 'linear',
    yLabel: 'Median latency (ms)',
    xLabel: asymptotic
      ? 'nₛₚ · tₛₚ = 0.6nₛₚ'
      : resilient
        ? 'nₛₚ · tₛₚ=⌈0.6nₛₚ⌉ · qₛₚ=⌈0.8nₛₚ⌉'
        : '(nₛₚ/tₛₚ)',
    title: `${resilient && panelKey === 'lan' ? 'Composed LAN' : panelLabels[panelKey]} · ${phaseTitle}`,
    width: kind === 'low' ? 700 : kind === 'asymptotic' ? 465 : 700,
    height: kind === 'low' ? 320 : kind === 'asymptotic' ? 585 : 610,
    xTickIndices: asymptotic || resilient ? [0, 3, 6, 9] : undefined,
    legendColumns: resilient ? (panelKey === 'local' ? 2 : 3) : 3,
    showLegend: resilient,
    dataKey: `${kind}-${phaseTitle.toLowerCase().replaceAll(' ', '-')}-${panelKey}-${index}`,
  })}</article>`;
}

function renderLow(id) {
  const phase = lowSlides[id];
  if (!phase) return null;
  const dataset = ssoLowThreshold[phase.key];
  const panels = ['client', 'provider', 'lan', 'wan'];
  return slideFrame(
    `AUX · ${phase.title} — Low-Threshold Comparison`,
    'low',
    panels.map((panelKey, index) => chartPanel({ dataset, panelKey, phaseTitle: phase.title, kind: 'low', index })).join(''),
  );
}

function renderAsymptotic(id) {
  const phase = asymptoticSlides[id];
  if (!phase) return null;
  const dataset = ssoProportional[phase.key];
  const panels = ['client', 'lan', 'wan'];
  return slideFrame(
    `AUX · ${phase.title} — Asymptotic Comparison`,
    'asymptotic',
    panels.map((panelKey, index) => chartPanel({ dataset, panelKey, phaseTitle: phase.title, kind: 'asymptotic', index })).join(''),
  );
}

function renderResilient(id) {
  const phase = resilientSlides[id];
  if (!phase) return null;
  const dataset = resilientBackendScaling[phase.key];
  const panels = ['local', 'lan'];
  return slideFrame(
    `AUX · ${phase.title} — UpSPA vs RoUpSPA`,
    'resilient',
    panels.map((panelKey, index) => chartPanel({ dataset, panelKey, phaseTitle: phase.title, kind: 'resilient', index })).join(''),
  );
}

export function renderEvaluationAuxSlide(id) {
  return renderLow(id) || renderAsymptotic(id) || renderResilient(id);
}

export const evaluationAuxSlideIds = Object.freeze([
  ...Object.keys(lowSlides),
  ...Object.keys(asymptoticSlides),
  ...Object.keys(resilientSlides),
]);
