function escapeHtml(value = '') {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
}

export function renderComparisonAuxSlide(id, meta = {}) {
  const figure = comparisonFigures[id];
  if (!figure) return null;

  return `<div class="slide-shell comparison-source-slide" style="display:grid;grid-template-rows:auto minmax(0,1fr);gap:4px;min-height:0;padding-bottom:30px;box-sizing:border-box">
    <h2 style="font-size:36px;line-height:1.04;margin:0;max-width:none">${escapeHtml(figure.title)}</h2>
    <figure style="margin:0;min-height:0;width:100%;height:100%;display:flex;align-items:center;justify-content:center;overflow:hidden">
      <img src="${escapeHtml(figure.src)}" alt="${escapeHtml(figure.alt)}" loading="eager" decoding="sync" style="display:block;max-width:100%;max-height:100%;width:auto;height:auto;object-fit:contain;object-position:center">
    </figure>
  </div>`;
}

export const comparisonAuxSlideIds = Object.freeze(Object.keys(comparisonFigures));
