import Reveal from 'reveal.js';
import RevealNotes from 'reveal.js/plugin/notes/notes.esm.js';
import RevealSearch from 'reveal.js/plugin/search/search.esm.js';
import RevealMath from 'reveal.js/plugin/math/math.esm.js';
import 'reveal.js/dist/reveal.css';
import './styles/deck.css';
import './styles/rebuild.css';
import YAML from 'yaml';
import deckText from './deck.yaml?raw';
import routeText from './web-route.yaml?raw';
import contentText from './content.yaml?raw';
import configText from '../../presentation.config.yaml?raw';
import { mathMacros } from './math-macros.js';
import { renderCoreSlide } from './slides/core.js';
import { renderBackupSlide } from './slides/backup.js';
import { renderEditableSlide } from './slides/content.js';
import { webContent } from './web-content.js';

const deckDoc = YAML.parse(deckText);
const routeDoc = YAML.parse(routeText);
const contentDoc = YAML.parse(contentText);
const config = YAML.parse(configText);
const editableContent = contentDoc.slides || contentDoc;
const sourceSlides = deckDoc.slides || deckDoc;
const sourceById = new Map(sourceSlides.map((slide) => [slide.id, slide]));

function normalizeAudienceText(value) {
  if (typeof value === 'string') {
    return value
      .replace(/^\s*(?:BACKUP|Backup|AUX|Aux)\s*(?:[·—:\-]\s*)?/, '')
      ;
  }
  if (Array.isArray(value)) return value.map(normalizeAudienceText);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, normalizeAudienceText(item)]));
  }
  return value;
}

const slideMeta = (routeDoc.slides || routeDoc).map((routeEntry) => {
  const sourceId = routeEntry.sourceId || routeEntry.id;
  const source = sourceById.get(sourceId);
  if (!source) throw new Error(`Unknown sourceId in web route: ${sourceId}`);
  const content = webContent[routeEntry.id]
    || editableContent[routeEntry.id]
    || editableContent[sourceId];
  const merged = content
    ? { ...source, ...routeEntry, ...content, content, title: content.title || routeEntry.title || source.title }
    : { ...source, ...routeEntry };
  if (merged.route === 'core') {
    delete merged.originId;
    delete merged.returnTarget;
  } else if (routeEntry.originId) {
    merged.returnTarget = routeEntry.originId;
  }
  return normalizeAudienceText(merged);
});
const byId = new Map(slideMeta.map((slide) => [slide.id, slide]));

const sectionDefaults = {
  title: ['Title', '#0b8f8c'],
  problem: ['Problem', '#b84d4d'],
  lineage: ['SPA lineage', '#68788a'],
  upspa: ['UpSPA', '#0b8f8c'],
  roupspa: ['RoUpSPA', '#7b61a8'],
  alternatives: ['Synchronization alternatives', '#d17722'],
  results: ['Implementation & results', '#164a7b'],
  conclusion: ['Conclusions', '#3f7b5a'],
  genealogy: ['Genealogy', '#68788a'],
  questions: ['Q&A', '#0b8f8c'],
};

function safe(value = '') {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
}

function sectionKey(meta) {
  if (meta.sectionKey) return meta.sectionKey;
  if (meta.route === 'backup') {
    const origin = byId.get(meta.originId || meta.returnTarget);
    if (origin) return sectionKey(origin);
  }
  const map = {
    title: 'title',
    'password-problem': 'problem',
    'spa-lineage': 'lineage',
    upspa: 'upspa',
    roupspa: 'roupspa',
    alternatives: 'alternatives',
    'implementation-results': 'results',
    conclusion: meta.id === 'academic-genealogy' ? 'genealogy' : meta.id === 'thank-you' ? 'questions' : 'conclusion',
  };
  return map[meta.section] || 'conclusion';
}

function sectionLabel(meta) {
  return meta.sectionLabel || sectionDefaults[sectionKey(meta)]?.[0] || meta.section;
}

function sectionColor(meta) {
  return sectionDefaults[sectionKey(meta)]?.[1] || '#164a7b';
}

function renderNotes(meta) {
  const notes = meta.speakerNotes || {};
  const cues = notes.cues || [];
  const refs = meta.sourceRefs || [];
  return `<aside class="notes">
Estimated time: ${meta.estimatedSeconds || 0} seconds

Main point: ${safe(notes.main || meta.title)}

${cues.map((cue) => `- ${safe(cue)}`).join('\n')}

Transition: ${safe(notes.transition || '')}

Skip option: ${safe(notes.skip || 'Do not skip.')}

Possible jury question: ${safe(notes.jury || '—')}

Answer pointer: ${safe(notes.pointer || '—')}

[Sources]
${refs.map((ref) => `- ${safe(ref)}`).join('\n')}
  </aside>`;
}

function makeSlide(meta) {
  const key = sectionKey(meta);
  const section = document.createElement('section');
  section.id = meta.id;
  section.dataset.route = meta.route;
  section.dataset.sectionGroup = key;
  section.dataset.sectionLabel = sectionLabel(meta);
  section.dataset.estimatedSeconds = meta.estimatedSeconds || 0;
  section.dataset.originId = meta.originId || meta.returnTarget || '';
  section.classList.add(`${key}-slide`);
  if (meta.route === 'backup') section.classList.add('backup-slide');
  section.style.setProperty('--section-color', sectionColor(meta));
  const content = meta.content
    ? renderEditableSlide(meta, config)
    : meta.route === 'backup'
      ? renderBackupSlide(meta.id, meta)
      : renderCoreSlide(meta.id, meta, config);
  const logoStrip = '<div class="global-logo-strip" aria-label="Affiliations"><img src="assets/koc-logo.png" alt="Koç University"><img src="assets/ku-crypto.png" alt="Koç University Cryptography, Security, and Privacy Research Group"></div>';
  section.innerHTML = `${content}${logoStrip}${renderNotes(meta)}`;
  section.querySelectorAll('.return-link').forEach((link) => link.remove());
  if (meta.route === 'backup') {
    const title = section.querySelector('h2');
    if (title) {
      title.innerHTML = title.innerHTML
        .trim()
        .replace(/^\s*(?:BACKUP|Backup|AUX|Aux)\s*(?:[·—:\-]\s*)?/i, '');
    }
    section.querySelectorAll('.section-kicker').forEach((kicker) => {
      const normalized = (kicker.textContent || '')
        .replace(/^\s*(?:BACKUP|Backup|AUX|Aux)\s*(?:[·—:\-]\s*)?/i, '')
        .replace(/\b(?:AUX|BACKUP)\b/gi, '')
        .trim();
      if (normalized) kicker.textContent = normalized;
      else kicker.remove();
    });
  }
  return section;
}

const coreSlides = slideMeta.filter((slide) => slide.route === 'core');
const coreIds = new Set(coreSlides.map((slide) => slide.id));
const backupsByOrigin = new Map(coreSlides.map((slide) => [slide.id, []]));
const orphanBackups = [];
for (const backup of slideMeta.filter((slide) => slide.route === 'backup')) {
  const parent = backup.originId || backup.returnTarget;
  if (!parent || !coreIds.has(parent)) orphanBackups.push(backup);
  else backupsByOrigin.get(parent).push(backup);
}

function buildDeck() {
  if (orphanBackups.length) {
    throw new Error(`Aux slides need a valid main originId/returnTarget: ${orphanBackups.map((slide) => slide.id).join(', ')}`);
  }
  const slidesRoot = document.getElementById('slides');
  for (const core of coreSlides) {
    const details = backupsByOrigin.get(core.id) || [];
    if (!details.length) {
      slidesRoot.append(makeSlide(core));
      continue;
    }
    const stack = document.createElement('section');
    stack.className = 'stack';
    stack.dataset.sectionGroup = sectionKey(core);
    stack.dataset.sectionLabel = sectionLabel(core);
    stack.style.setProperty('--section-color', sectionColor(core));
    const coreSlide = makeSlide(core);
    coreSlide.classList.add('has-backups');
    stack.append(coreSlide);
    details.forEach((detail) => stack.append(makeSlide(detail)));
    slidesRoot.append(stack);
  }
}

function addPhysicalPageNumbers() {
  const physicalSlides = [...document.querySelectorAll('#slides section[id]')];
  const total = physicalSlides.length;
  physicalSlides.forEach((slide, index) => {
    const number = document.createElement('div');
    number.className = 'physical-page-number';
    number.setAttribute('aria-label', `Slide ${index + 1} of ${total}`);
    number.textContent = `${index + 1} / ${total}`;
    slide.append(number);
  });
}

function groupedCoreSlides() {
  const groups = [];
  for (const slide of coreSlides) {
    const key = sectionKey(slide);
    let group = groups.find((entry) => entry.key === key);
    if (!group) {
      group = { key, label: sectionLabel(slide), color: sectionColor(slide), slides: [] };
      groups.push(group);
    }
    group.slides.push(slide);
  }
  return groups;
}

function buildRoadmap() {
  const roadmap = document.getElementById('roadmap');
  const groups = groupedCoreSlides();
  roadmap.style.gridTemplateColumns = `repeat(${groups.length}, minmax(0,1fr))`;
  const compactLabel = (group) => ({ alternatives: 'Sync', results: 'Results' }[group.key] || group.label);
  roadmap.innerHTML = groups.map((group) => `<a href="#/${group.slides[0].id}" data-group="${group.key}" style="--roadmap-color:${group.color}">${safe(compactLabel(group))}</a>`).join('');
}

function buildWaterfall() {
  const groups = groupedCoreSlides();
  const nav = document.createElement('nav');
  nav.className = 'waterfall-nav';
  nav.setAttribute('aria-label', 'Slide navigator');
  const navText = (value = '') => String(value).replace(/^\s*(?:BACKUP|AUX)\s*(?:[·—:\-]\s*)?/i, '');
  nav.innerHTML = `<button class="waterfall-trigger" type="button" aria-expanded="false" aria-controls="waterfall-panel"><span>Deck map</span><i aria-hidden="true">⌄</i></button><div class="waterfall-panel" id="waterfall-panel">${groups.map((group) => `<section class="waterfall-section" data-group="${group.key}" style="--section-color:${group.color}"><a class="waterfall-section-link" href="#/${group.slides[0].id}">${safe(group.label)}</a><div>${group.slides.map((slide) => {
    const details = backupsByOrigin.get(slide.id) || [];
    return `<div class="waterfall-branch"><a class="waterfall-core" data-slide-id="${slide.id}" href="#/${slide.id}">${safe(slide.navLabel || slide.title)}</a>${details.length ? `<div class="waterfall-details">${details.map((detail, index) => `<span class="waterfall-detail" data-slide-id="${detail.id}" data-parent-id="${slide.id}">${index + 1}. ${safe(navText(detail.navLabel || detail.title))}</span>`).join('')}</div>` : ''}</div>`;
  }).join('')}</div></section>`).join('')}</div>`;
  document.body.append(nav);
  const trigger = nav.querySelector('.waterfall-trigger');
  const panel = nav.querySelector('.waterfall-panel');
  panel.inert = true;
  const close = (restoreFocus = false) => {
    nav.classList.remove('open');
    trigger.setAttribute('aria-expanded', 'false');
    panel.inert = true;
    if (restoreFocus) trigger.focus();
  };
  trigger.addEventListener('click', () => {
    const open = nav.classList.toggle('open');
    trigger.setAttribute('aria-expanded', String(open));
    panel.inert = !open;
  });
  nav.querySelectorAll('a').forEach((link) => link.addEventListener('click', () => close(false)));
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && nav.classList.contains('open')) {
      event.preventDefault();
      event.stopImmediatePropagation();
      close(true);
    }
  });
  document.addEventListener('pointerdown', (event) => {
    if (!nav.contains(event.target)) close();
  });
}

function updateNavigation(currentSlide) {
  if (!currentSlide) return;
  const group = currentSlide.dataset.sectionGroup || currentSlide.parentElement?.dataset.sectionGroup || '';
  const activeId = currentSlide.id;
  const parentId = currentSlide.dataset.originId || activeId;
  document.querySelectorAll('#roadmap a').forEach((item) => item.classList.toggle('active', item.dataset.group === group));
  document.querySelectorAll('.waterfall-section').forEach((item) => item.classList.toggle('active', item.dataset.group === group));
  document.querySelectorAll('.waterfall-core').forEach((item) => {
    const isActive = item.dataset.slideId === parentId;
    item.classList.toggle('active', isActive);
    if (isActive) item.setAttribute('aria-current', 'page');
    else item.removeAttribute('aria-current');
  });
  document.querySelectorAll('.waterfall-detail').forEach((item) => item.classList.toggle('active', item.dataset.slideId === activeId));
  const active = document.querySelector(`.waterfall-nav [data-slide-id="${CSS.escape(activeId)}"]`);
  active?.scrollIntoView({ block: 'nearest' });
  document.body.dataset.currentSection = group;
}

buildDeck();
addPhysicalPageNumbers();
buildRoadmap();
buildWaterfall();

const coreSeconds = coreSlides.reduce((sum, slide) => sum + Number(slide.estimatedSeconds || 0), 0);
if (coreSeconds > 2340) {
  console.warn(`Core route is ${(coreSeconds / 60).toFixed(1)} minutes; target is at most 39.0 minutes.`);
}

const mathjaxUrl = new URL('mathjax/tex-chtml.js', document.baseURI).href;
let reveal;
let flowControls;

function verticalSlidesAt(horizontalIndex) {
  const horizontal = reveal.getHorizontalSlides()[horizontalIndex];
  const nested = horizontal?.querySelectorAll(':scope > section') || [];
  return nested.length ? [...nested] : [horizontal];
}

function navigateMain(delta) {
  const { h = 0 } = reveal.getIndices();
  const target = h + delta;
  if (target >= 0 && target < reveal.getHorizontalSlides().length) reveal.slide(target, 0);
}

function navigateStory(delta) {
  const { v = 0 } = reveal.getIndices();
  if (v === 0) {
    const fragments = reveal.availableFragments();
    if (delta > 0 && fragments.next) {
      reveal.nextFragment();
      return;
    }
  }
  navigateMain(delta);
}

function navigateBackup(delta) {
  const { h = 0, v = 0 } = reveal.getIndices();
  const vertical = verticalSlidesAt(h);
  const target = v + delta;
  if (target >= 0 && target < vertical.length) reveal.slide(h, target);
}

function buildFlowControls() {
  const nav = document.createElement('nav');
  nav.className = 'flow-controls';
  nav.setAttribute('aria-label', 'Slide flow controls');
  nav.innerHTML = `<div class="flow-pad"><button type="button" data-flow="up" aria-label="Previous vertical slide" aria-keyshortcuts="ArrowUp K">↑</button><button type="button" data-flow="left" aria-label="Previous horizontal slide" aria-keyshortcuts="ArrowLeft H">←</button><button type="button" data-flow="down" aria-label="Next vertical slide" aria-keyshortcuts="ArrowDown J">↓</button><button type="button" data-flow="right" aria-label="Next horizontal slide" aria-keyshortcuts="ArrowRight L">→</button></div>`;
  document.body.append(nav);
  nav.querySelector('[data-flow="left"]').addEventListener('click', () => navigateMain(-1));
  nav.querySelector('[data-flow="right"]').addEventListener('click', () => navigateMain(1));
  nav.querySelector('[data-flow="up"]').addEventListener('click', () => navigateBackup(-1));
  nav.querySelector('[data-flow="down"]').addEventListener('click', () => navigateBackup(1));
  return nav;
}

function updateFlowControls() {
  if (!flowControls) return;
  const { h = 0, v = 0 } = reveal.getIndices();
  const vertical = verticalSlidesAt(h);
  flowControls.querySelector('[data-flow="left"]').disabled = h === 0;
  flowControls.querySelector('[data-flow="right"]').disabled = h >= reveal.getHorizontalSlides().length - 1;
  flowControls.querySelector('[data-flow="up"]').disabled = v === 0;
  flowControls.querySelector('[data-flow="down"]').disabled = v >= vertical.length - 1;
}

flowControls = buildFlowControls();

reveal = new Reveal({
  width: 1600,
  height: 900,
  margin: 0,
  minScale: 0.2,
  maxScale: 2,
  hash: true,
  history: true,
  center: false,
  controls: false,
  controlsTutorial: false,
  progress: true,
  slideNumber: false,
  transition: 'fade',
  transitionSpeed: 'fast',
  backgroundTransition: 'fade',
  navigationMode: 'default',
  touch: false,
  keyboard: {
    37: () => navigateStory(-1),
    39: () => navigateStory(1),
    38: () => navigateBackup(-1),
    40: () => navigateBackup(1),
    72: () => navigateStory(-1),
    76: () => navigateStory(1),
    75: () => navigateBackup(-1),
    74: () => navigateBackup(1),
    33: () => navigateStory(-1),
    34: () => navigateStory(1),
    78: () => navigateStory(1),
    80: () => navigateStory(-1),
    32: (event) => navigateStory(event?.shiftKey ? -1 : 1),
  },
  pdfSeparateFragments: false,
  plugins: [RevealNotes, RevealSearch, RevealMath.MathJax3],
  mathjax3: {
    mathjax: mathjaxUrl,
    tex: {
      inlineMath: [['\\(', '\\)']],
      displayMath: [['\\[', '\\]']],
      macros: mathMacros,
    },
    options: { skipHtmlTags: ['script', 'noscript', 'style', 'textarea', 'pre'] },
  },
});

window.Reveal = reveal;
window.__DECK_META__ = slideMeta;

const refreshNavigation = (event) => {
  updateNavigation(event.currentSlide || reveal.getCurrentSlide());
  updateFlowControls();
};
reveal.on('ready', refreshNavigation);
reveal.on('slidechanged', refreshNavigation);
reveal.on('fragmentshown', refreshNavigation);
reveal.on('fragmenthidden', refreshNavigation);
reveal.initialize();
