import { sequenceDiagram } from './components.js';

const identificationActors = [
  { id: 'user', label: 'User', kind: 'user' },
  { id: 'sp', label: 'Storage providers \\(SP_i\\)', kind: 'sp' },
];

function recoveryFields(resilient) {
  return resilient
    ? '\\(ssk, R^{sp}, K_0, ctr_{id}\\)'
    : '\\(ssk, R^{sp}, K_0\\)';
}

export function renderToprfInteractionBlock({
  password = 'pwd',
  sameShares = false,
  detailed = false,
} = {}) {
  if (!detailed) {
    const suffix = password === 'pwd' ? '' : ' \\(' + password + '\\)';
    return `<div class="protocol-interaction toprf-interaction is-compact-minimal" data-protocol-interaction="toprf" data-span="user-sp">
      <div class="interaction-heading"><strong>Interactive TOPRF${suffix}</strong></div>
    </div>`;
  }

  const passwordMath = `\\(${password}\\)`;
  const shareText = sameShares ? 'same provider shares \\(\\{k_i\\}\\)' : 'provider shares \\(\\{k_i\\}\\)';
  return `<div class="protocol-interaction toprf-interaction${detailed ? ' is-detailed' : ''}" data-protocol-interaction="toprf" data-span="user-sp">
    <div class="interaction-heading"><strong>Interactive TOPRF(${passwordMath})</strong><span>User ↔ \\(SP_i\\)</span></div>
    <div class="interaction-parties" aria-hidden="true"><b>User</b><i>↔</i><b>\\(SP_i\\)</b></div>
    <div class="interaction-exchange"><span>blinded ${passwordMath} request →</span><span>← valid partial evaluations · ${shareText}</span></div>
  </div>`;
}

export function renderIdentificationBlock({
  mode = 'compact',
  password = 'pwd',
  oldPassword = false,
  resilient = false,
} = {}) {
  if (mode === 'compact') {
    return `<div class="protocol-interaction identification-interaction is-compact-minimal ${resilient ? 'is-resilient' : 'is-upspa'}" data-protocol-interaction="identification" data-span="user-sp">
      <div class="interaction-heading"><strong>Identification</strong></div>
    </div>`;
  }

  const detail = sequenceDiagram({
    actors: identificationActors,
    steps: [
      { number: 1, from: 'user', to: 'sp', label: '\\(Uid\\)' },
      { number: 2, from: 'sp', to: 'user', label: 'OK / FAIL' },
      {
        number: 3,
        from: 'user',
        to: 'sp',
        interaction: renderToprfInteractionBlock({ password }),
      },
      { number: 4, from: 'sp', to: 'user', label: 'Return \\(c_{id}\\)' },
      { number: 5, from: 'user', to: 'user', local: true, label: `Decrypt \\(c_{id}\\) with \\(F_K(${password})\\)` },
      { number: 6, from: 'user', to: 'user', local: true, label: `Recover ${recoveryFields(resilient)}` },
    ],
  });

  return `<div class="identification-component is-detailed" data-identification-mode="detailed">${detail}</div>`;
}

export function identificationStep({
  number = 1,
  password = 'pwd',
  oldPassword = false,
  resilient = false,
} = {}) {
  return {
    number,
    from: 'user',
    to: 'sp',
    interaction: renderIdentificationBlock({ mode: 'compact', password, oldPassword, resilient }),
  };
}

export function interactiveToprfStep({
  number,
  password = 'pwd',
  sameShares = false,
} = {}) {
  return {
    number,
    from: 'user',
    to: 'sp',
    interaction: renderToprfInteractionBlock({ password, sameShares }),
  };
}
