export function lineChart({
  labels,
  series,
  yMax,
  yMin,
  yLabel = 'Time (ms)',
  xLabel = '',
  title = '',
  width = 920,
  height = 390,
  baseline = 0,
  yScale = 'linear',
  xTickIndices,
  legendColumns,
  showLegend = true,
  dataKey = '',
}) {
  const columns = Math.max(1, Math.min(series.length, legendColumns || Math.min(series.length, 3)));
  const legendRows = showLegend ? Math.ceil(series.length / columns) : 0;
  const pad = { l: 105, r: 30, t: 62, b: showLegend ? 110 + legendRows * 38 : 82 };
  const innerW = width - pad.l - pad.r;
  const innerH = height - pad.t - pad.b;
  const allValues = series.flatMap((s) => s.values);
  const positiveValues = allValues.filter((value) => value > 0);
  const max = yMax ?? Math.max(...allValues) * (yScale === 'log' ? 1.16 : 1.08);
  const min = yMin ?? (yScale === 'log' ? Math.min(...positiveValues) * 0.82 : baseline);
  if (!(max > min) || (yScale === 'log' && min <= 0)) throw new Error(`Invalid ${yScale} chart domain for ${title}`);
  const x = (i) => pad.l + (labels.length === 1 ? innerW/2 : i * innerW/(labels.length-1));
  const logMin = Math.log10(min);
  const logMax = Math.log10(max);
  const y = (v) => pad.t + innerH - (yScale === 'log'
    ? ((Math.log10(v) - logMin) / (logMax - logMin)) * innerH
    : ((v - min) / (max - min)) * innerH);
  const tickValues = yScale === 'log'
    ? Array.from({ length: Math.max(0, Math.floor(logMax) - Math.ceil(logMin) + 1) }, (_, index) => 10 ** (Math.ceil(logMin) + index))
    : Array.from({ length: 5 }, (_, index) => min + (max - min) * index / 4);
  const formatTick = (value) => {
    if (value >= 1000) return `${Number((value / 1000).toPrecision(3))}k`;
    if (value >= 10) return value.toFixed(0);
    if (value >= 1) return Number(value.toPrecision(3)).toString();
    return Number(value.toPrecision(2)).toString();
  };
  const grid = tickValues.map((value) => {
    const yy = y(value);
    return `<path d="M${pad.l} ${yy}H${pad.l+innerW}"/><text x="${pad.l-12}" y="${yy+5}">${formatTick(value)}</text>`;
  }).join('');
  const plots = series.map((s) => {
    const d = s.values.map((v,i) => `${i?'L':'M'}${x(i)} ${y(v)}`).join(' ');
    const points = s.values.map((v,i) => `<circle cx="${x(i)}" cy="${y(v)}" r="4"/>`).join('');
    const dashArray = s.dashArray || (s.dash ? '10 8' : '');
    return `<g class="plot" data-series="${esc(s.name)}" data-point-count="${s.values.length}" style="--series:${s.color}"><path d="${d}" ${dashArray ? `stroke-dasharray="${dashArray}"` : ''}/>${points}</g>`;
  }).join('');
  const visibleTickIndices = new Set(xTickIndices || labels.map((_, index) => index));
  const xTicks = labels.map((label,i) => visibleTickIndices.has(i) ? `<text x="${x(i)}" y="${pad.t+innerH+32}">${esc(label)}</text>` : '').join('');
  const legendTop = height - legendRows * 38 + 8;
  const legend = showLegend ? series.map((s,i) => {
    const row = Math.floor(i / columns);
    const column = i % columns;
    const dashArray = s.dashArray || (s.dash ? '10 8' : '');
    return `<g transform="translate(${pad.l + column * (innerW / columns)} ${legendTop + row * 38})"><path d="M0 0h36" style="stroke:${s.color}" ${dashArray ? `stroke-dasharray="${dashArray}"` : ''}/><circle cx="18" cy="0" r="4" style="fill:${s.color}"/><text x="48" y="8">${esc(s.name)}</text></g>`;
  }).join('') : '';
  return `<svg class="line-chart" data-chart-key="${esc(dataKey)}" data-y-scale="${esc(yScale)}" data-series-count="${series.length}" data-label-count="${labels.length}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(title || yLabel)}"><title>${esc(title || yLabel)}</title><text class="chart-title" x="${width/2}" y="34">${esc(title)}</text><g class="grid">${grid}</g><g class="axis"><path d="M${pad.l} ${pad.t}V${pad.t+innerH}H${pad.l+innerW}"/>${xTicks}<text class="axis-label" transform="translate(30 ${pad.t+innerH/2}) rotate(-90)">${esc(yLabel)}</text><text class="axis-label" x="${pad.l+innerW/2}" y="${pad.t+innerH+68}">${esc(xLabel)}</text></g>${plots}<g class="legend">${legend}</g></svg>`;
}

export function comparisonBars({ groups, labels, max, unit = 'ms' }) {
  return `<div class="comparison-bars">${groups.map((group) => `<div class="bar-group"><div class="bar-label">${group.label}</div>${labels.map((label, i) => `<div class="bar-row"><span>${label}</span><i class="bar upspa" style="--w:${(group.upspa[i]/max)*100}%"></i><em>${group.upspa[i].toFixed(2)}</em><i class="bar roupspa" style="--w:${(group.roupspa[i]/max)*100}%"></i><em>${group.roupspa[i].toFixed(2)}</em></div>`).join('')}</div>`).join('')}<div class="bar-legend"><span class="upspa-dot"></span>UpSPA <span class="roupspa-dot"></span>RoUpSPA <small>${unit}</small></div></div>`;
}

