import { sectionKicker } from '../components.js';

function safe(value = '') {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
}

function interpolate(template = '', config = {}) {
  return String(template).replace(/\{\{config\.([A-Za-z0-9_]+)\}\}/g, (_, key) => safe(config[key] ?? ''));
}

function renderGenealogy(meta, config) {
  const content = meta.content || {};
  const genealogy = Array.isArray(config.genealogy) ? config.genealogy : [];
  const nodes = [0, 1, 2].map((index) => {
    const person = genealogy[index] || {};
    const incomplete = !person.name || !person.role || !person.institution || /TODO/i.test(JSON.stringify(person));
    const initials = incomplete
      ? '?'
      : person.name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join('').toUpperCase();
    const portrait = person.photo
      ? `<img src="${safe(person.photo)}" alt="${safe(person.name)}">`
      : `<span aria-hidden="true">${safe(initials)}</span>`;
    return `<article class="gene-node ${incomplete ? 'todo' : ''}"><div class="portrait">${portrait}</div><strong>${safe(person.name || 'TODO')}</strong><span>${safe(person.role || 'Role not configured')}</span><small>${safe(person.institution || 'Institution not configured')}</small></article>`;
  });
  return `<div class="slide-shell">${sectionKicker(content.kicker || 'Academic genealogy')}<h2>${content.title || meta.title}</h2><p class="lead genealogy-lead">${content.lead || ''}</p><div class="genealogy">${nodes.join('')}</div></div>`;
}

export function renderEditableSlide(meta, config) {
  const content = meta.content || {};
  if (content.layout === 'genealogy') return renderGenealogy(meta, config);
  if (content.layout === 'raw') return interpolate(content.body || '', config);
  const kicker = content.kicker || meta.sectionLabel || meta.section || 'Slide';
  const title = interpolate(content.title || meta.title || '', config);
  const body = interpolate(content.body || '', config);
  return `<div class="slide-shell">${sectionKicker(kicker)}<h2>${title}</h2>${body}</div>`;
}
