function takeaway(text, kind = '') {
  return `<div class="takeaway-strip ${kind}"><b>Takeaway</b><span>${text}</span></div>`;
}

function chartPanelLegend(series, columns = 2, compact = false) {
  const label = (name) => compact
    ? name.replace('registration', 'reg.').replace('authentication', 'auth.')
    : name;
  return `<div class="chart-panel-legend" style="--legend-columns:${columns}">${series.map((item) => `<span class="${item.dash || item.dashArray ? 'dashed' : ''}" style="--legend-color:${item.color}"><i></i>${label(item.name)}</span>`).join('')}</div>`;
}

function exactFigure(path, alt, caption = '') {
  return `<figure class="exact-figure"><img src="${path}" alt="${alt}">${caption ? `<figcaption>${caption}</figcaption>` : ''}</figure>`;
}

function protocolScreenshot(path, alt, caption) {
  return `<div class="screenshot-stage">${exactFigure(path, alt, caption)}</div>`;
}

function diagram(actorsList, steps, finalLabel) {
  return sequenceDiagram({ actors: actorsList, steps, finalLabel });
}

function downloadedSecurityIcon(fileName, label) {
  return `<span class="downloaded-security-icon"><img src="assets/security-icons/${fileName}.svg" alt="${label} icon"></span>`;
}

function serviceCategory(label, iconName) {
  return `<article>${downloadedSecurityIcon(iconName, label)}<strong>${label}</strong></article>`;
}

function lineageProtocol(kind) {
  const isThreshold = kind === 'TSPA';
  const provider = isThreshold ? 'Storage providers' : 'Storage provider';
  const registrationSteps = isThreshold
    ? ['Distribute protected helper material across \\(n_{sp}\\) providers', 'Register one high-entropy service verifier']
    : ['Store password-protected helper state', 'Register one high-entropy service verifier'];
  const authenticationSteps = isThreshold
    ? ['Run OPRF-based protection with the providers', 'Combine at least \\(t_{sp}\\) responses and recover the service credential', 'Authenticate without sending \\(pwd\\)']
    : ['Open the helper state and recover the service credential', 'Authenticate without sending \\(pwd\\)'];
  const row = (label, steps, offset) => `<article class="legacy-zone"><h3>${label}</h3><div class="legacy-zone-flow">${steps.map((step, index) => `<div class="fragment" data-fragment-index="${offset + index}"><b>${index + 1}</b><span>${step}</span></div>`).join('<i>→</i>')}</div></article>`;
  return `<div class="legacy-protocol" data-protocol="${kind.toLowerCase()}"><div class="legacy-actors"><span>${provider}</span><span>User</span><span>Website / Login server</span></div>${row('Registration', registrationSteps, 0)}${row('Authentication', authenticationSteps, registrationSteps.length)}<div class="legacy-principle"><strong>${isThreshold ? '\\(t_{sp}\\) of \\(n_{sp}\\)' : 'One password'}</strong><span>${isThreshold ? 'OPRF-based protection and threshold recovery' : 'The login server receives only a high-entropy verifier'}</span></div></div>`;
}

function recoveryNodes(states) {
  return states.map((state, index) => `<span class="recovery-node ${state}"><b>SP${index + 1}</b><small>${state === 'active' ? 'ACTIVE' : state === 'recovering' ? 'RECOVERING' : 'OFFLINE / STALE'}</small></span>`).join('');
}

function recoveryStage({ index, title, states, detail, fragmentClass = '' }) {
  const fragmentIndex = fragmentClass ? ` data-fragment-index="${index}"` : '';
  return `<article class="recovery-scene ${fragmentClass}"${fragmentIndex}><div class="recovery-stage-label">Stage ${index + 1}</div><h3>${title}</h3><div class="recovery-nodes">${recoveryNodes(states)}</div><div class="recovery-detail">${detail}</div></article>`;
}

function animatedRecovery() {
  return `<div class="recovery-animation">
    ${recoveryStage({ index: 0, title: 'Two providers have missed committed state', states: ['active','active','active','active','active','stale','stale'], detail: '<b>SP1–SP5</b> are synchronized. <b>SP6</b> and <b>SP7</b> are offline or stale.' })}
    ${recoveryStage({ index: 1, title: 'SP6 returns and repairs from quorum R₆', states: ['active','active','active','active','active','recovering','stale'], detail: String.raw`SP6 queries \(R_6=\{SP1,SP2,SP3,SP4,SP5\}\), verifies signatures and quorum evidence, selects the largest valid counter, and repairs its local state.`, fragmentClass: 'fragment fade-in-then-out' })}
    ${recoveryStage({ index: 2, title: 'SP7 can now recover through a quorum that includes SP6', states: ['active','active','active','active','active','active','recovering'], detail: String.raw`After SP6 becomes ACTIVE, SP7 queries a valid \(q_{sp}\)-provider recovery quorum \(R_7\) that may include SP6 and repeats the same checks.`, fragmentClass: 'fragment fade-in-then-out' })}
    ${recoveryStage({ index: 3, title: 'All seven providers are ACTIVE and synchronized', states: ['active','active','active','active','active','active','active'], detail: 'Recovery copies only the freshest valid signed ciphertext. No password, plaintext, or TOPRF participation is required.', fragmentClass: 'fragment fade-in' })}
  </div>`;
}

function miniResilienceChart(phase, label) {
  return `<article class="mini-chart-card">${lineChart({
    labels: resilienceLabels,
    series: [
      { name: 'UpSPA', color: '#164a7b', values: resilienceLocal[phase].upspa },
      { name: 'RoUpSPA', color: '#7b61a8', values: resilienceLocal[phase].roupspa },
    ],
    yMax: Math.max(...resilienceLocal[phase].roupspa) * 1.12,
    yLabel: 'Local client (ms)',
    xLabel: 'n/t/q',
    title: label,
    width: 460,
    height: 330,
  })}<div class="lan-endpoint"><b>Composed LAN at 10/6/8</b><span>UpSPA ${resilienceLan[phase].upspa.at(-1).toFixed(3)} ms</span><span>RoUpSPA ${resilienceLan[phase].roupspa.at(-1).toFixed(3)} ms</span></div></article>`;
}

function endpointComparison() {
  const max = 30;
  return `<div class="grouped-endpoints"><div class="endpoint-key">${endpointNames.map((name, i) => `<span style="--key:${endpointColors[i]}">${name}</span>`).join('')}</div>${endpointRows.map(([phase, values]) => `<article><h3>${phase}</h3><div>${values.map((value, i) => {
    const isLargestPasswordBar = phase === 'Password update' && i === 0;
    return `<span class="endpoint-bar${isLargestPasswordBar ? ' label-inside' : ' label-above'}" style="--h:${(value / max) * 100}%;--bar:${endpointColors[i]}"><i>${value.toFixed(3)}</i></span>`;
  }).join('')}</div></article>`).join('')}</div>`;
}

