const raw = String.raw;
const auxText = (value = '') => String(value).replace(/\bAUX\b|\bAux\b/g, 'Aux');

const upspaActors = [
  { id: 'sp', label: 'Storage providers · SPᵢ', kind: '' },
  { id: 'user', label: 'User · U(uid, pwd)', kind: 'user' },
  { id: 'ls', label: 'Login server · LSⱼ', kind: 'ls' },
];

const roupspaActors = [
  { id: 'sp', label: 'Active providers · SPᵢ', kind: '' },
  { id: 'user', label: 'User · U(uid, pwd)', kind: 'user' },
  { id: 'ls', label: 'Login server · LSⱼ', kind: 'ls' },
];

function frame(meta, kicker, fallbackTitle, origin, fallbackSource, body) {
  const title = auxText(meta?.title || fallbackTitle);
  const fallbackFooter = meta?.citation ? '' : sourceFooter(fallbackSource);
  return raw`<div class="slide-shell">
    <h2>${title}</h2>
    ${body}
    ${fallbackFooter}
  </div>`;
}

function compactSequence(options, minHeight = 405) {
  return sequenceDiagram({ ...options, dense: true })
    .replace('style="--actor-columns:', `style="min-height:${minHeight}px;--actor-columns:`);
}

function denseTable(headers, rows, widths = []) {
  const header = headers.map((cell, index) => raw`<th style="padding:5px 7px;font-size:12px;line-height:1.1;${widths[index] ? `width:${widths[index]}` : ''}">${cell}</th>`).join('');
  const body = rows.map((row) => raw`<tr>${row.map((cell, index) => raw`<td style="padding:5px 7px;font-size:12.5px;line-height:1.16;${widths[index] ? `width:${widths[index]}` : ''}">${cell}</td>`).join('')}</tr>`).join('');
  return raw`<table class="status-table" style="margin-top:8px;table-layout:fixed"><thead><tr>${header}</tr></thead><tbody>${body}</tbody></table>`;
}

function proofChain(items) {
  return raw`<div class="game-chain">${items.map(([name, description], index) => raw`
    <div class="game-step"><strong>${name}</strong><span>${description}</span></div>${index < items.length - 1 ? '<div class="game-arrow">↓</div>' : ''}
  `).join('')}</div>`;
}

function miniCards(items, columns = 3) {
  return raw`<div style="display:grid;grid-template-columns:repeat(${columns},1fr);gap:12px;margin-top:10px">${items.map(([title, text, color = 'var(--provider)']) => raw`
    <div style="padding:12px 14px;border-top:4px solid ${color};background:rgba(255,255,255,.62);min-height:92px">
      <strong style="display:block;font-size:16px">${title}</strong>
      <span style="display:block;margin-top:5px;font-size:13.5px;line-height:1.22;color:var(--ink-soft)">${text}</span>
    </div>`).join('')}</div>`;
}

function protocolTags(items) {
  return raw`<div style="position:absolute;right:0;top:48px;text-align:right">${items.map(([text, kind]) => tag(text, kind)).join('')}</div>`;
}

function renderUpSpaSetup(meta) {
  const body = raw`${protocolTags([['all nₛₚ providers', ''], ['no Store/Discard', 'user']])}${compactSequence({
    actors: upspaActors.slice(0, 2).reverse(),
    steps: [
      { number: '1-5', from: 'user', to: 'user', local: true, label: raw`\(R_{sp}\leftarrow\{0,1\}^{\lambda}\); \((K,\{k_i\})\leftarrow\mathsf{TOPRFGen}\); \((ssk,svk)\leftarrow\mathsf{SignKeyGen}\); \(K_0\leftarrow\mathsf{KeyGen}\); \(c_{id}\leftarrow\mathsf{Enc}_{F_K(pwd)}(ssk\|R_{sp}\|K_0)\)` },
      { number: 6, from: 'user', to: 'sp', label: raw`\(\langle uid,svk,c_{id},k_i\rangle\)` },
      { number: 7, from: 'sp', to: 'user', label: raw`\(\mathsf{OK}/\mathsf{FAIL}\); accept only if no setup record exists`, state: 'committed' },
    ],
  }, 420)}
  <div class="claim" style="margin-top:2px;padding:10px 14px;font-size:15px">Success requires \(\mathsf{OK}\) from every provider. The public \(uid\)-indexed setup record remains subject to deployment-side onboarding protection.</div>`;
  return frame(meta, 'Aux · UpSPA protocol', 'UpSPA Setup - complete phase', 'upspa-lifecycle', 'Thesis, UpSPA Construction, Fig. “UpSPA setup phase”.', body);
}

