function renderUpSpaChallenges(meta) {
  const challenges = [
    ['1 · Login-server boundary', 'Keep pwd and deterministic password-derived values away from login servers.', 'Domain-specific high-entropy account secret'],
    ['2 · Subthreshold privacy', 'Prevent fewer than tₛₚ providers from testing password guesses offline.', 'Threshold OPRF output protects cᵢd'],
    ['3 · Independent updates', 'Rotate one account secret without coupling every account; change pwd without rewriting them.', 'Compact root + per-site layer'],
    ['4 · Namespace/domain separation', 'Avoid public-only account names and cross-domain reuse after setup.', 'Hidden Rₛₚ routing + domain binding'],
    ['5 · Authorization/freshness', 'A lookup value alone must not authorize replacement; old valid ciphertexts must not become current.', 'AE, signatures, counters, timestamp'],
    ['6 · One committed outcome', 'Intermediate state must not become an accepted completed phase.', 'Pending/committed + all-provider finalization'],
    ['7 · Ordinary deployment', 'Keep LS outside threshold crypto while stating the all-provider liveness cost.', 'Verifier-only LS; explicit DoS boundary'],
  ];
  const body = raw`<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin-top:8px">${challenges.map(([name, need, mechanism]) => raw`
    <div style="padding:11px 12px;border-top:4px solid var(--user);background:rgba(255,255,255,.62);min-height:150px">
      <strong style="display:block;font-size:15px">${name}</strong>
      <span style="display:block;margin-top:7px;font-size:13px;line-height:1.2;color:var(--ink-soft)">${need}</span>
      <em style="display:block;margin-top:10px;font-style:normal;font-size:12px;font-weight:800;color:var(--login)">${mechanism}</em>
    </div>`).join('')}</div>
    <div class="warning-box" style="margin-top:12px;padding:10px 14px;font-size:14px"><strong>Scope:</strong> the hidden-namespace prediction claim needs hidden-input output unpredictability; collision resistance alone supplies binding, not unpredictability.</div>`;
  return frame(meta, 'Aux · UpSPA design', 'UpSPA design challenges - full map', 'upspa-design-challenges', 'Thesis, UpSPA Threat Model, “Design Challenges of UpSPA”.', body);
}

function renderUpSpaThreat(meta) {
  const left = [
    ['Adversary', 'Static, non-uniform PPT malicious adversary; the corruption set is fixed for the complete execution.'],
    ['Corruption', raw`At most \(t_{sp}-1\) storage providers, \(n_{ls}-1\) login servers, and \(n_{user}-1\) users.`],
    ['Honest target', 'At least one honest user and one honest login server; a corrupted target LS is outside the guarantee.'],
    ['Channels and time', 'Authenticated server channels, synchronous bounded delay, and the timestamp clock assumptions used by Password Update.'],
    ['Availability', raw`Authentication needs \(t_{sp}\) valid responses; every UpSPA state-changing boundary needs all \(n_{sp}\).`],
  ];
  const right = [
    ['Password claim', 'The view adds no new offline verification predicate; it does not make a human password guess negligible.'],
    ['Cryptographic assumptions', 'TOPRF PRF + receiver-input obliviousness; AE IND-CPA, integrity, and key binding; EUF-CMA signatures; collision-resistant hash.'],
    ['Completed phases', 'Safety only after protocol-defined final acknowledgements; interrupted finalization and repair are outside the theorem.'],
    ['Trusted endpoint', 'Malware, keyloggers, memory scraping, malicious extensions/OS/client code are excluded.'],
    ['Not claimed', 'Anonymity, traffic-analysis resistance, account recovery, permanent provider replacement, adaptive/mobile corruption, or general crash recovery.'],
  ];
  const list = (items, color) => raw`<div style="display:grid;gap:8px">${items.map(([title, text]) => raw`<div style="padding:10px 13px;border-left:4px solid ${color};background:rgba(255,255,255,.62)"><strong style="display:block;font-size:15px">${title}</strong><span style="display:block;margin-top:3px;font-size:13px;line-height:1.2;color:var(--ink-soft)">${text}</span></div>`).join('')}</div>`;
  const body = raw`<div class="backup-columns" style="gap:22px;margin-top:6px">${list(left, 'var(--user)')}${list(right, 'var(--danger)')}</div>`;
  return frame(meta, 'Aux · UpSPA security', 'UpSPA threat model - exact boundary', 'upspa-threat-model', 'Thesis, UpSPA Threat Model, §§ System Model and Threat Model.', body);
}

function renderUpSpaSimulator(meta) {
  const rows = [
    ['Setup', 'Sample simulated root/signing/TOPRF material and dummy cᵢd; expose the corrupted-provider view.', 'Only after all nₛₚ accept.'],
    ['Registration', 'Use TOPRF/logical tables; create dummy account ciphertext and pending provider tuples; reproduce LS decision.', 'After LS accepts, Store, and all nₛₚ final acknowledgements.'],
    ['Authentication', 'Read committed logical root/account values, ignore pending state, select maximum valid counter, reproduce verifier decision.', 'No pending state and no Store/Discard.'],
    ['Secret update', 'Sample new account secret; keep dummy replacement pending; reproduce LS decision and exact finalization.', 'After LS accepts, Store, and all nₛₚ final acknowledgements.'],
    ['Password update', 'Generate fresh TOPRF key/shares; dummy cᵢd,new; sign exact uid‖cᵢd,new‖kᵢ,new‖time‖i; keep pending.', 'After Store and all nₛₚ final acknowledgements.'],
  ];
  const chain = proofChain([
    ['G₀', 'stopped real execution'],
    ['G₁', 'replace TOPRF values and honest-receiver transcripts'],
    ['G₂', 'replace identification plaintexts'],
    ['G₃', 'replace account plaintexts'],
    ['G₄', 'ideal FUpSPA + Sim'],
  ]);
  const body = raw`<div class="split-60" style="gap:24px;align-items:start"><div>${denseTable(['Phase', 'Simulator state/view', 'Ideal success point'], rows, ['15%', '57%', '28%'])}</div><div>${chain}<div class="claim" style="margin-top:10px;padding:10px 13px;font-size:14px">Pending/committed mechanics stay local to \(\mathsf{Sim}\); \(\mathcal F_{UpSPA}\) contains only the logical result of a completed phase.</div></div></div>`;
  return frame(meta, 'Aux · UpSPA proof', 'UpSPA simulator - phase-to-ideal map', 'upspa-security', 'Thesis, UpSPA Security Analysis, Simulation Behavior and Games G₀-G₄.', body);
}

function renderUpSpaAdvantage(meta) {
  const body = raw`<div class="equation-box" style="margin-top:12px;font-size:18px;line-height:1.35">
    \[\begin{aligned}
    \mathsf{Adv}^{\mathsf{real/ideal}}_{UpSPA,\mathcal F_{UpSPA}}(\mathcal A)\le{}&\mathsf{Adv}^{prf}_{TOPRF}(\mathcal B_{prf})\\
    &+q_{\mathsf{id}}\mathsf{Adv}^{ind\text{-}cpa}_{AE}(\mathcal B_{cpa,id})
    +q_{\mathsf{sp}}\mathsf{Adv}^{ind\text{-}cpa}_{AE}(\mathcal B_{cpa,sp}).
    \end{aligned}\]
  </div>
  ${miniCards([
    [raw`\(q_{\mathsf{id}}\)`, 'honest encryptions producing cᵢd or cᵢd,new'],
    [raw`\(q_{\mathsf{sp}}\)`, 'honest account-ciphertext encryptions; this proof count is not RoUpSPA’s availability quorum'],
    ['Completion', 'only committed completed phases; interrupted finalization is outside the theorem'],
  ], 3)}
  <div class="warning-box" style="margin-top:14px;padding:10px 14px;font-size:14px"><strong>Proof-accounting note.</strong> The theorem assumes receiver-input obliviousness and G₁ says it replaces honest-receiver transcripts, but the displayed final bound has no separately named receiver-input-obliviousness term. This transcription preserves the thesis formula; it does not invent one.</div>`;
  return frame(meta, 'Aux · UpSPA proof', 'UpSPA final real/ideal advantage bound', 'upspa-security', 'Thesis, UpSPA Security Analysis, Completion of the Theorem.', body);
}

