function renderNotation(meta) {
  const items = [
    [raw`\(n_{sp}\)`, 'number of providers'], [raw`\(t_{sp}\)`, 'TOPRF/authentication threshold'], [raw`\(q_{sp}\)`, 'durable-write and repair quorum'],
    [raw`\(uid\)`, 'public user identifier'], [raw`\(ls_j\)`, 'authenticated service label'], [raw`\(pwd,pwd_{new}\)`, 'current and new password'],
    [raw`\(R_{sp}\)`, 'hidden routing secret'], [raw`\(R^{ls_j}\)`, 'service-specific secret'], [raw`\(K, k_i\)`, 'TOPRF key and share'],
    [raw`\(K_0\)`, 'account encryption key'], [raw`\(c_{id}\)`, 'protected root record'], [raw`\(c_{sp}\)`, 'account ciphertext'],
    [raw`\(SUid_{l,i,j}\)`, 'UpSPA provider-specific ID'], [raw`\(SUid_{l,j}\)`, 'RoUpSPA shared routing ID'], [raw`\(vInfo_j\)`, 'service verifier'],
    [raw`\(ctr_{id}\)`, 'RoUpSPA root counter'], [raw`\(ctr_{ac}\)`, 'account counter'], [raw`\(ssk,svk\)`, 'user signing keys'],
    ['PENDING', 'not readable; awaits decision'], ['CURRENT', 'accepted readable record'], ['ACTIVE / STALE', 'may serve / must repair'],
  ];
  const body = raw`<div class="notation-grid compact-notation">${items.map(([symbol, meaning]) => raw`<div class="notation-item"><strong>${symbol}</strong><span>${meaning}</span></div>`).join('')}</div>
  <div class="notation-boundary"><strong>Keep the thresholds separate:</strong> \(t_{sp}\) controls cryptographic recovery; \(q_{sp}\) controls durable writes and repair.</div>`;
  return frame(meta, 'Aux · Quick reference', 'Notation and state vocabulary', 'upspa-two-layer-state', 'Active thesis symbols, UpSPA Construction, and RoUpSPA Construction.', body);
}

