export function renderBackupSlide(id, meta) {
  const evaluationAux = renderEvaluationAuxSlide(id, meta);
  if (evaluationAux) return evaluationAux;

  const comparisonAux = renderComparisonAuxSlide(id, meta);
  if (comparisonAux) return comparisonAux;

  const renderer = renderers[id];
  if (!renderer) {
    return frame(meta, 'Aux', meta?.title || 'Aux slide', meta?.returnTarget || meta?.originId || 'thank-you', 'Aux slide metadata.', '<p class="lead">Slide content unavailable.</p>');
  }
  return renderer(meta);
}
